# BEFORE: synchronous -- caller waits for the full report generation
def generate_report(request):
    data = fetch_large_dataset(request.filters)     # can take 5-40 seconds
    pdf_bytes = render_pdf(data)                      # another few seconds
    save_to_storage(pdf_bytes, request.report_id)
    return {"status": "done", "report_id": request.report_id}

# AFTER: enqueue the work, return immediately, let a worker do the slow part
def generate_report(request):
    queue.publish("report_jobs", {
        "report_id": request.report_id,
        "filters": request.filters,
    })
    return {"status": "accepted", "report_id": request.report_id}

# Runs in a separate worker process, consuming from "report_jobs"
def report_worker(message):
    data = fetch_large_dataset(message["filters"])
    pdf_bytes = render_pdf(data)
    save_to_storage(pdf_bytes, message["report_id"])
    mark_report_ready(message["report_id"])   # caller polls this, or gets a webhook

