def upload_image(request):
    file_bytes = request.files["image"].read()
    original_url = save_to_storage(file_bytes, folder="originals")

    queue.publish("resize_jobs", {"original_url": original_url})
    return {"status": "uploaded", "url": original_url}

# separate, independently-scalable worker process
def resize_worker(message):
    file_bytes = fetch_from_storage(message["original_url"])
    for size in ("thumbnail", "medium"):
        resized = resize_image(file_bytes, size=size)
        save_to_storage(resized, folder=size)
    mark_resize_complete(message["original_url"])

def place_order(order_data):
    with database.transaction():
        order_id = database.insert("orders", order_data)
        database.insert("outbox", {
            "event_type": "order_placed",
            "payload": {"order_id": order_id, **order_data},
            "published": False,
        })
        # both inserts commit together, or neither does -- no gap between them
    return order_id

# separate relay process, running continuously:
def outbox_relay():
    for row in database.query("SELECT * FROM outbox WHERE published = false"):
        broker.publish(row["event_type"], row["payload"])   # at-least-once, retried on failure
        database.update("outbox", row.id, {"published": True})
